import React, { useEffect, useState } from "react";

const STORAGE_KEY = "japTrackerData";

export default function JapTracker() {
  const [days, setDays] = useState([]);
  const [showReminder, setShowReminder] = useState(false);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setDays(JSON.parse(saved));
    } else {
      setDays(
        Array.from({ length: 30 }, () => ({
          jap: false,
          satsang: false,
          prarthana: false
        }))
      );
    }

    // Daily reminder popup (once per day)
    const today = new Date().toDateString();
    const lastShown = localStorage.getItem("reminderDate");

    if (lastShown !== today) {
      setShowReminder(true);
      localStorage.setItem("reminderDate", today);
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    if (days.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(days));
    }
  }, [days]);

  const toggle = (index, field) => {
    const updated = [...days];
    updated[index][field] = !updated[index][field];
    setDays(updated);
  };

  // Completed days
  const completedDays = days.filter(
    d => d.jap && d.satsang && d.prarthana
  ).length;

  // 🔥 Streak calculation
  const streak = (() => {
    let count = 0;
    for (let i = days.length - 1; i >= 0; i--) {
      if (days[i].jap && days[i].satsang && days[i].prarthana) {
        count++;
      } else break;
    }
    return count;
  })();

  const progressPercent = Math.round((completedDays / 30) * 100);

  return (
    <div style={container}>
      <h3>📿 30-Day Jap Tracker</h3>

      {/* 🔥 Streak */}
      <p>🔥 Streak: <b>{streak} days</b></p>

      {/* 🟢 Progress Ring */}
      <div style={ringContainer}>
        <svg width="120" height="120">
          <circle
            cx="60"
            cy="60"
            r="50"
            stroke="#eee"
            strokeWidth="10"
            fill="none"
          />
          <circle
            cx="60"
            cy="60"
            r="50"
            stroke="#4caf50"
            strokeWidth="10"
            fill="none"
            strokeDasharray="314"
            strokeDashoffset={314 - (314 * progressPercent) / 100}
            strokeLinecap="round"
            transform="rotate(-90 60 60)"
          />
        </svg>
        <div style={ringText}>{progressPercent}%</div>
      </div>

      <p>Completed: <b>{completedDays}/30</b></p>

      {/* 🎯 Badge */}
      {completedDays === 30 && (
        <div style={badge}>🎉 30/30 Jap Complete! Krupa thay 🙏</div>
      )}

      {/* 📅 Table */}
      <div style={{ overflowX: "auto" }}>
        <table style={table}>
          <thead>
            <tr>
              <th>Day</th>
              <th>Jap</th>
              <th>Satsang</th>
              <th>Prarthana</th>
            </tr>
          </thead>
          <tbody>
            {days.map((d, i) => (
              <tr key={i}>
                <td>{i + 1}</td>

                <td onClick={() => toggle(i, "jap")} style={cell}>
                  {d.jap ? "✔️" : "⬜"}
                </td>

                <td onClick={() => toggle(i, "satsang")} style={cell}>
                  {d.satsang ? "✔️" : "⬜"}
                </td>

                <td onClick={() => toggle(i, "prarthana")} style={cell}>
                  {d.prarthana ? "✔️" : "⬜"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 🔔 Reminder Popup */}
      {showReminder && (
        <div style={popup}>
          <p>📿 Aaje 10 min jap bhulsho nai 🙏</p>
          <button onClick={() => setShowReminder(false)}>OK</button>
        </div>
      )}
    </div>
  );
}

const container = {
  background: "#fff",
  padding: "15px",
  borderRadius: "10px",
  marginTop: "20px",
  textAlign: "center"
};

const table = {
  width: "100%",
  borderCollapse: "collapse",
  marginTop: "15px"
};

const cell = {
  cursor: "pointer",
  fontSize: "20px"
};

const badge = {
  background: "#4caf50",
  color: "#fff",
  padding: "10px",
  borderRadius: "10px",
  margin: "10px 0",
  fontWeight: "bold"
};

const ringContainer = {
  position: "relative",
  width: "120px",
  margin: "auto"
};

const ringText = {
  position: "absolute",
  top: "40px",
  left: "0",
  right: "0",
  fontWeight: "bold"
};

const popup = {
  position: "fixed",
  bottom: "20px",
  left: "50%",
  transform: "translateX(-50%)",
  background: "#111",
  color: "#fff",
  padding: "15px",
  borderRadius: "10px"
};
